package main

import "fmt"

func named() (n int) {
	defer func() { n *= 2 }()
	n = 1
	return n + 2
}

func unnamed() int {
	n := 1
	defer func() { n *= 2 }()
	return n + 2
}

func main() {
	fmt.Println(named(), unnamed())
}

package main

import (
	"fmt"
	"sync"
)

type Counter struct {
	mu     sync.RWMutex
	counts map[string]int
}

func (c *Counter) Get(key string) int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.counts[key]
}

func (c Counter) Incr(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.counts[key]++
}

func main() {
	c := &Counter{counts: map[string]int{}}
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c.Incr("hits")
		}()
	}
	wg.Wait()
	fmt.Println(c.Get("hits"))
}
